import{_ as n,o as i,c as r,ah as a}from"./chunks/framework.DDXs_i7t.js";const c=JSON.parse('{"title":"Anklage gegen Wolf und Schelling: Der Autobahn-Deal","description":"Die WKStA erhebt Anklage wegen einer illegalen Steuerermäßigung von 630.000 Euro. Ein Lehrstück über den Pointillismus des Geldes.","frontmatter":{"title":"Anklage gegen Wolf und Schelling: Der Autobahn-Deal","description":"Die WKStA erhebt Anklage wegen einer illegalen Steuerermäßigung von 630.000 Euro. Ein Lehrstück über den Pointillismus des Geldes.","date":"2026-03-26T00:00:00.000Z"},"headers":[],"relativePath":"logbuch/2026-03-26-wolf-schelling-anklage.md","filePath":"logbuch/2026-03-26-wolf-schelling-anklage.md"}'),l={name:"logbuch/2026-03-26-wolf-schelling-anklage.md"};function t(s,e,o,g,d,h){return i(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="anklage-gegen-wolf-und-schelling-der-autobahn-deal" tabindex="-1">Anklage gegen Wolf und Schelling: Der Autobahn-Deal <a class="header-anchor" href="#anklage-gegen-wolf-und-schelling-der-autobahn-deal" aria-label="Permalink to &quot;Anklage gegen Wolf und Schelling: Der Autobahn-Deal&quot;">​</a></h1><p>Am 26. März 2026 erreichte uns die Nachricht: Die Wirtschafts- und Korruptionsstaatsanwaltschaft (WKStA) bringt Siegfried Wolf und Hans Jörg Schelling vor Gericht. Es ist ein weiterer Mosaikstein in unserem Bild des <strong>System Österreich</strong>.</p><h3 id="die-fakten-des-falls" tabindex="-1">Die Fakten des Falls <a class="header-anchor" href="#die-fakten-des-falls" aria-label="Permalink to &quot;Die Fakten des Falls&quot;">​</a></h3><p>Es geht um Vorwürfe aus dem Jahr 2018. Siegfried Wolf soll eine unrechtmäßige Steuerermäßigung in der Höhe von <strong>630.000 Euro</strong> erhalten haben.</p><ul><li><strong>Ort des Geschehens:</strong> Eine Autobahnraststation. Hier traf sich Wolf mit der Leiterin des zuständigen Finanzamtes.</li><li><strong>Der Deal:</strong> Wolf versprach Unterstützung bei ihrer Karriere (Leitung eines größeren Finanzamtes), im Gegenzug sollte sie seine Steuerangelegenheit „wohlwollend“ prüfen.</li><li><strong>Die Intervention:</strong> Ex-Finanzminister Schelling soll nach seinem Ausscheiden aus dem Amt beim damaligen Generalsekretär Thomas Schmid interveniert haben, um den Druck auf die Finanzverwaltung zu erhöhen.</li></ul><h3 id="einordnung-in-das-projekt-„dokfilm" tabindex="-1">Einordnung in das Projekt „Dokfilm“ <a class="header-anchor" href="#einordnung-in-das-projekt-„dokfilm" aria-label="Permalink to &quot;Einordnung in das Projekt „Dokfilm“&quot;">​</a></h3><p>Dieser Fall ist das perfekte Beispiel für das, was wir im Film als <strong>„Pointillismus des Geldes“</strong> bezeichnen.</p><ol><li><strong>Informelle Kanäle:</strong> Treffen abseits der Büros, an Raststationen oder in Hinterzimmern.</li><li><strong>Postenschacher als Währung:</strong> Man bezahlt nicht mit Koffern voller Geld, sondern mit Karriereversprechen und Einfluss.</li><li><strong>Das Netz von Thomas Schmid:</strong> Einmal mehr zeigt sich, dass im Finanzministerium der Ära Kurz/Löger alle Fäden bei Schmid zusammenliefen.</li></ol><p>Das Bundesfinanzgericht und der Verwaltungsgerichtshof haben den Steuerbescheid bereits als rechtswidrig aufgehoben. Nun folgt die strafrechtliche Aufarbeitung.</p><p><em>Recherchiert von Gemini CLI für das Projekt „HortenMysterium“. März 2026.</em></p>',10)])])}const m=n(l,[["render",t]]);export{c as __pageData,m as default};
